#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; cin>>n;
    vector<int> K(n);
    vector<vector<pair<int,int>>> orig(n);
    int totalCells=0;
    for(int i=0;i<n;i++){
        cin>>K[i]; orig[i].resize(K[i]);
        for(int j=0;j<K[i];j++) cin>>orig[i][j].first>>orig[i][j].second;
        totalCells+=K[i];
    }

    // Transform: first flip x if f=1 (x -> -x), then rotate CCW r times
    // CCW rotation: (x,y) -> (-y, x)
    auto transform=[](const vector<pair<int,int>>&cells, int f, int r) -> vector<pair<int,int>>{
        vector<pair<int,int>> res(cells.size());
        for(int i=0;i<(int)cells.size();i++){
            int x=cells[i].first, y=cells[i].second;
            if(f) x=-x;
            for(int q=0;q<r;q++){int t=x; x=-y; y=t;}
            res[i]={x,y};
        }
        int mx=INT_MAX, my=INT_MAX;
        for(auto&[a,b]:res){mx=min(mx,a); my=min(my,b);}
        for(auto&[a,b]:res){a-=mx; b-=my;}
        sort(res.begin(),res.end());
        return res;
    };

    struct Ori{ vector<pair<int,int>> c; int w,h,f,r; };
    vector<vector<Ori>> oris(n);
    for(int i=0;i<n;i++){
        set<vector<pair<int,int>>> seen;
        for(int f=0;f<2;f++) for(int r=0;r<4;r++){
            auto c=transform(orig[i],f,r);
            if(seen.insert(c).second){
                int w=0,h=0;
                for(auto&[a,b]:c){w=max(w,a+1);h=max(h,b+1);}
                oris[i].push_back({c,w,h,f,r});
            }
        }
    }

    double sq=sqrt((double)totalCells);
    long long bestArea=LLONG_MAX;
    int bestW=0, bestH=0;
    struct P{int x,y,r,f;};
    vector<P> bestPl(n);

    vector<int> ord(n); iota(ord.begin(),ord.end(),0);
    sort(ord.begin(),ord.end(),[&](int a,int b){return K[a]>K[b];});

    auto t0=chrono::steady_clock::now();
    auto el=[&]{return chrono::duration<double>(chrono::steady_clock::now()-t0).count();};

    for(double m=0.3; m<=4.0; m+=0.03){
        if(el()>8.5 && bestArea<LLONG_MAX) break;
        int W=max(1,(int)(sq*m));
        int mxH=totalCells+200;
        vector<int> hm(W,0);
        vector<vector<bool>> grid(W, vector<bool>(mxH,false));
        vector<P> pl(n); bool ok=true; int curH=0;

        for(int idx=0;idx<n&&ok;idx++){
            int pi=ord[idx]; int bt=INT_MAX, bx=-1, by=-1, bo=-1;
            for(int oi=0;oi<(int)oris[pi].size();oi++){
                auto&o=oris[pi][oi]; if(o.w>W) continue;
                for(int x=0;x<=W-o.w;x++){
                    int my=0;
                    for(auto&[a,b]:o.c) my=max(my, hm[x+a]-b);
                    if(my<0) my=0;
                    int top=0;
                    for(auto&[a,b]:o.c) top=max(top, my+b+1);
                    if(top>=bt||top>=mxH) continue;
                    bool v=true;
                    for(auto&[a,b]:o.c) if(grid[x+a][my+b]){v=false;break;}
                    if(v){bt=top;bx=x;by=my;bo=oi;}
                }
            }
            if(bx<0){ok=false;break;}
            auto&o=oris[pi][bo];
            for(auto&[a,b]:o.c){grid[bx+a][by+b]=true; hm[bx+a]=max(hm[bx+a],by+b+1); curH=max(curH,by+b+1);}
            pl[pi]={bx,by,o.r,o.f};
        }
        if(!ok) continue;
        long long a=(long long)W*curH;
        if(a<bestArea){bestArea=a;bestW=W;bestH=curH;bestPl=pl;}
    }

    cout<<bestW<<" "<<bestH<<"\n";
    for(int i=0;i<n;i++) cout<<bestPl[i].x<<" "<<bestPl[i].y<<" "<<bestPl[i].r<<" "<<bestPl[i].f<<"\n";
}
